export const LESSON_DEPTH_ES: Record<MoleculeLessonId | QuestLessonId, LessonDepth> = {
  hydrogen: { simple: "Dos átomos de hidrógeno comparten electrones para formar H₂, la molécula más ligera.", deeper: "H₂ tiene un enlace sigma H–H corto y fuerte, y no presenta ángulo de enlace porque solo contiene dos átomos. Su entalpía de disociación es de unos 436 kJ/mol: formar el enlace libera energía y romperlo requiere energía." },
  oxygen: { simple: "El oxígeno gaseoso está formado por dos átomos unidos como O₂.", deeper: "O₂ contiene un enlace doble y es paramagnético porque sus orbitales moleculares tienen dos electrones desapareados. Esta estructura electrónica ayuda a explicar su reactividad, aunque la molécula sea suficientemente estable para constituir gran parte del aire." },
  nitrogen: { simple: "El nitrógeno gaseoso tiene dos átomos unidos por un enlace triple muy fuerte.", deeper: "El enlace N≡N tiene una entalpía de enlace cercana a 945 kJ/mol, por lo que muchas reacciones deben superar una gran barrera energética para romperlo. Esta estabilidad cinética explica por qué el nitrógeno atmosférico es poco reactivo, aunque algunos compuestos de nitrógeno sí reaccionan con facilidad." },
  water: { simple: "Una molécula de agua tiene un oxígeno unido a dos hidrógenos y su forma es angular, no recta.", deeper: "El ángulo H–O–H es de unos 104,5°; el oxígeno tiene dos pares solitarios y una disposición electrónica aproximadamente sp³. La forma angular hace que los dipolos de enlace se sumen y produzcan un dipolo neto; los puentes de hidrógeno influyen mucho en las propiedades del agua líquida." },
  "carbon-dioxide": { simple: "El dióxido de carbono tiene un carbono entre dos oxígenos en línea recta.", deeper: "El CO₂ es lineal, con un ángulo O–C–O de 180°, y el carbono central suele describirse como sp. Cada enlace C=O es polar, pero sus dipolos iguales y opuestos se cancelan; por eso la molécula completa es apolar." },
  methane: { simple: "El metano tiene un átomo de carbono unido a cuatro hidrógenos.", deeper: "Los cuatro enlaces C–H apuntan hacia los vértices de un tetraedro y forman ángulos cercanos a 109,5°. Esta geometría concuerda con el modelo de enlaces sp³ y distribuye las direcciones de enlace alrededor del carbono." },
  ammonia: { simple: "El amoníaco tiene un nitrógeno unido a tres hidrógenos y un par solitario.", deeper: "El amoníaco es una pirámide trigonal con un ángulo H–N–H cercano a 107°, porque el par solitario repele más que los pares de enlace. El nitrógeno se describe a menudo con una disposición electrónica sp³ aproximada, y la forma piramidal da a NH₃ un dipolo neto." },
  "hydrogen-chloride": { simple: "El cloruro de hidrógeno es un par de átomos, hidrógeno y cloro, unidos por un enlace polar.", deeper: "El HCl es una molécula diatómica lineal: su eje de enlace es el único eje molecular y no hay ángulo de enlace. La diferencia de electronegatividad hace polar el enlace H–Cl; al disolverse en agua, el HCl se ioniza ampliamente." },
  "hydrogen-peroxide": { simple: "El peróxido de hidrógeno tiene dos oxígenos unidos, cada uno con un hidrógeno.", deeper: "El H₂O₂ no es plano: el giro alrededor del enlace simple O–O y la repulsión entre pares solitarios favorecen una forma torcida. El enlace O–O es relativamente débil frente a muchos enlaces O–H, lo que ayuda a explicar su descomposición en agua y oxígeno." },
  "hydrogen-cyanide": { simple: "En el cianuro de hidrógeno, H, C y N están en línea como H–C≡N.", deeper: "El HCN es lineal y el carbono tiene dos regiones electrónicas, compatibles con una descripción sp. El enlace triple C≡N es corto y fuerte; aunque la molécula sea recta, sus extremos distintos producen un dipolo importante." },
  ethane: { simple: "El etano tiene dos carbonos unidos por un enlace simple y tres hidrógenos en cada carbono.", deeper: "Cada carbono del etano tiene una disposición aproximadamente tetraédrica y suele describirse como sp³. El enlace sigma C–C permite la rotación y da conformaciones alternadas y eclipsadas con energías torsionales distintas." },
  ethylene: { simple: "El etileno tiene dos carbonos unidos por un enlace doble y dos hidrógenos en cada carbono.", deeper: "Cada carbono es aproximadamente sp² e trigonal plano, con ángulos cercanos a 120°. La superposición lateral de orbitales p forma el enlace pi, que impide la rotación libre alrededor de C=C sin perder esa superposición." },
  acetylene: { simple: "El acetileno tiene un enlace triple carbono–carbono y un hidrógeno en cada extremo.", deeper: "Cada carbono de H–C≡C–H es sp y la geometría es lineal, con un ángulo de 180°. El enlace triple contiene un enlace sigma y dos pi, por lo que el esqueleto de carbonos es corto y rígido." },
  methanol: { simple: "El metanol es un alcohol de un carbono con un grupo –OH; es tóxico y no debe beberse.", deeper: "El carbono de CH₃OH es aproximadamente tetraédrico, mientras que el oxígeno tiene dos pares solitarios y una región C–O–H angular. El grupo hidroxilo puede donar y aceptar puentes de hidrógeno, lo que contribuye a que el metanol se mezcle con agua." },
  ethanol: { simple: "El etanol es un alcohol de dos carbonos; su grupo –OH ayuda a que se mezcle con agua.", deeper: "El grupo hidroxilo del etanol forma puentes de hidrógeno con el agua, mientras que el pequeño grupo etilo limita la parte apolar de la molécula. El equilibrio entre estas interacciones permite que el etanol y el agua sean miscibles en todo el intervalo de composición." },
  "dimethyl-ether": { simple: "El éter dimetílico tiene un oxígeno entre dos grupos pequeños de carbono.", deeper: "El oxígeno de CH₃OCH₃ tiene dos pares solitarios y una disposición C–O–C angular; cada carbono es aproximadamente tetraédrico. El oxígeno puede aceptar puentes de hidrógeno del agua, pero no donarlos, así que sus interacciones difieren de las del etanol aunque compartan fórmula." },
  formaldehyde: { simple: "El formaldehído tiene un carbono con doble enlace al oxígeno y enlaces a dos hidrógenos.", deeper: "El carbono del grupo carbonilo en CH₂O es aproximadamente sp² y trigonal plano, con ángulos cercanos a 120°. El enlace C=O polar hace que el formaldehído reaccione con nucleófilos y sea importante en la química de resinas." },
  "formic-acid": { simple: "El ácido fórmico es el ácido carboxílico más pequeño y contiene un carbono.", deeper: "Su grupo carboxilo es aproximadamente plano y la densidad electrónica se comparte entre los enlaces C–O. En agua es un ácido débil; la resonancia entre dos oxígenos estabiliza su base conjugada." },
  "acetic-acid": { simple: "El ácido acético es el ácido que da su sabor agrio al vinagre diluido.", deeper: "El ácido acético tiene un metilo unido a un carboxilo casi plano; su base conjugada reparte la carga por resonancia entre dos oxígenos. Su pKa acuoso es cerca de 4,76 a temperatura ambiente, así que es un ácido débil que solo se ioniza parcialmente en agua diluida." },
  "hydrogen-sulfide": { simple: "El sulfuro de hidrógeno tiene un azufre unido a dos hidrógenos y puede ser muy tóxico.", deeper: "El H₂S es angular, pero su ángulo H–S–H es de unos 92°, mucho menor que el del agua, por las diferencias en el enlace del azufre. Es un ácido débil en agua y puede ser muy tóxico; el olfato no es una advertencia confiable de exposición." },
  phosphine: { simple: "La fosfina tiene un fósforo unido a tres hidrógenos y es muy tóxica.", deeper: "La PH₃ es una pirámide trigonal con un ángulo H–P–H cercano a 93,5°, mucho menor que el del amoníaco. Su enlace no se describe bien con la misma hibridación sp³ fuerte que se usa para NH₃; el par solitario permanece en gran medida centrado en el fósforo." },
  "hydrogen-fluoride": { simple: "El fluoruro de hidrógeno tiene un hidrógeno unido a un flúor.", deeper: "El HF es una molécula diatómica polar sin ángulo de enlace y su enlace H–F es muy fuerte para un haluro de hidrógeno. En fases condensadas y en agua, los puentes de hidrógeno y la ionización afectan su comportamiento; el HF concentrado es extremadamente peligroso." },
  "carbon-tetrachloride": { simple: "El tetracloruro de carbono tiene un carbono unido a cuatro átomos de cloro.", deeper: "El CCl₄ es tetraédrico, con ángulos cercanos a 109,5°, y sus cuatro enlaces C–Cl polares están distribuidos simétricamente. Los dipolos se cancelan, por lo que la molécula es apolar a pesar de sus enlaces polares." },
  chloroform: { simple: "El cloroformo tiene un carbono unido a un hidrógeno y tres cloros.", deeper: "El carbono de CHCl₃ tiene geometría aproximadamente tetraédrica, pero sus sustituyentes distintos impiden que se cancelen los dipolos de enlace. La molécula resultante es polar y la exposición puede dañar la salud; por eso terminó su uso anestésico histórico." },
  "mix-fizz": { simple: "Un ácido y el bicarbonato pueden reaccionar y formar dióxido de carbono, que se ve como burbujas.", deeper: "El bicarbonato acepta un protón y forma ácido carbónico, que puede descomponerse en agua y CO₂. El gas sale de la disolución en forma de burbujas; cuánto avanza la reacción depende del ácido, las cantidades y las condiciones." },
  "mix-slime": { simple: "Los iones de borato pueden unir algunas cadenas de PVA y hacer que la mezcla se estire como slime.", deeper: "Las especies de borato forman enlaces cruzados reversibles con grupos hidroxilo de las cadenas de PVA y crean una red viscoelástica. Como los enlaces pueden reorganizarse bajo esfuerzo, el material fluye, se estira y puede recuperar parte de su forma, en vez de quedar curado de manera permanente." },
  "mix-vanishing-film": { simple: "El agua puede separar las cadenas de una película de PVA soluble y dispersarla.", deeper: "El agua forma puentes de hidrógeno con los grupos hidroxilo del PVA y solvata las cadenas, lo que permite separarlas y dispersarlas. Disolverse es un proceso físico y no demuestra por sí solo que un material sea biodegradable o inocuo para el ambiente." },
  "mix-sticky-situation": { simple: "Las proteínas de los mejillones pueden adherirse a superficies mojadas mediante grupos químicos que interactúan con ellas.", deeper: "Los grupos catecol de DOPA pueden coordinarse con algunas superficies minerales que contienen metales y participar en la adhesión interfacial. También influyen la cohesión de la capa proteica, la química de la superficie, el pH y el estado de oxidación." },
  "mix-strand": { simple: "La seda de araña combina regiones ordenadas de proteínas con cadenas flexibles, lo que ayuda a que sea resistente y elástica.", deeper: "Los nanocristales de hojas beta unidos por puentes de hidrógeno pueden soportar carga, mientras que las regiones menos ordenadas se extienden y disipan energía. El equilibrio entre estas estructuras, la orientación de las fibras y la hidratación influye en la resistencia y la extensibilidad." },
  "mix-enzyme-helper": { simple: "Las proteasas son enzimas que ayudan a dividir las proteínas en partes más pequeñas.", deeper: "Las proteasas catalizan la hidrólisis de enlaces peptídicos y reducen la barrera de activación sin cambiar el equilibrio global de la reacción. El pH y la temperatura afectan la protonación del sitio activo y la estructura de la proteína, así que la actividad depende de las condiciones." },
  "atom-split": { simple: "Un núcleo de uranio-235 puede dividirse al absorber un neutrón y liberar energía y más neutrones.", deeper: "La captura de un neutrón puede excitar U-236, que a veces se fisiona y produce fragmentos y neutrones. Una fisión típica libera alrededor de 200 MeV, en su mayoría como energía cinética de los fragmentos, aunque los productos y la energía exactos varían." },
  "atom-tightest": { simple: "Los núcleos cercanos al hierro y al níquel están entre los más unidos por protón o neutrón.", deeper: "Los datos medidos muestran un máximo amplio de energía de enlace por nucleón en la región hierro–níquel; el máximo exacto depende del isótopo y del conjunto de datos. Esta tendencia ayuda a explicar por qué la fusión de núcleos ligeros y la fisión de núcleos muy pesados pueden liberar energía, pero no predice la velocidad de reacción." },
  "atom-alpha": { simple: "En la desintegración alfa, un núcleo inestable emite una partícula con dos protones y dos neutrones.", deeper: "La partícula alfa emitida es un núcleo de helio-4; por eso el número atómico del núcleo original baja en dos y su número másico en cuatro. El tunelamiento cuántico a través de la barrera de Coulomb explica cómo puede ocurrir la desintegración aunque una partícula clásica quedaría atrapada." },
  "atom-new-element": { simple: "Los científicos pueden intentar crear núcleos superpesados al chocar átomos, pero un núcleo predicho no es un elemento descubierto.", deeper: "La isla de estabilidad es una predicción de modelos de capas nucleares: algunos isótopos superpesados podrían durar más que sus vecinos, aunque su ubicación y vida siguen siendo inciertas. Los elementos nuevos se sintetizan e identifican de a pocos átomos; predecir un núcleo Z≥119 no demuestra que se haya descubierto." },
};
